import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, SessionContextUsage, SessionCost, SessionRateLimit } from 'claude-code'

import type { LimitSnapshot, LimitWindow } from '../types'
import {
  addSamples,
  alertsOf,
  barCells,
  cacheOf,
  costText,
  displayOf,
  expiredWarnKeys,
  labelOf,
  newlyCrossed,
  parseThresholds,
  report,
  resetIn,
  shortLine,
  toneOf,
  warnKeyOf,
  warnedIn,
} from './logic'
import type { Alert } from './logic'

const COMMAND = 'limits'
const TICK_MS = 60_000
const WARN_TOAST_MS = 8_000
const NARROW_COLUMNS = 80
const CLOSE_LABEL = '×'

const snapshot = atom({ plugin: 'limit-radar', key: 'snapshot' } as const, null)
const samples = atom({ plugin: 'limit-radar', key: 'samples' } as const, [])
const lastTurnEndAt = atom({ plugin: 'limit-radar', key: 'lastTurnEndAt' } as const, null)
const tick = atom({ plugin: 'limit-radar', key: 'tick' } as const, 0)
const isHidden = atom({ plugin: 'limit-radar', key: 'isHidden' } as const, false)
const dismissed = atom({ plugin: 'limit-radar', key: 'dismissed' } as const, [])
const sessionWarned = atom({ plugin: 'limit-radar', key: 'sessionWarned' } as const, {})

type Figures = { context: SessionContextUsage; rateLimits: readonly SessionRateLimit[]; cost?: SessionCost }

const snapshotOf = (figures: Figures, at: number): LimitSnapshot => {
  const next: LimitSnapshot = {
    at,
    windows: figures.rateLimits.map(limit =>
      limit.resetsAt === undefined
        ? { kind: limit.kind, percentUsed: limit.percentUsed }
        : { kind: limit.kind, percentUsed: limit.percentUsed, resetsAt: limit.resetsAt },
    ),
  }

  if (figures.context.percent !== undefined) {
    next.contextPercent = figures.context.percent
  }

  if (figures.context.tokens !== undefined) {
    next.contextTokens = figures.context.tokens
  }

  if (figures.cost !== undefined) {
    next.costUsd = figures.cost.usd
  }

  return next
}

type Settings = { showsStatus: boolean; thresholds: readonly number[] }

/**
 * Toasts each threshold once per window. A window with a reset time is
 * remembered in `$.store`, so the next session in the same window stays quiet;
 * one without a reset time can only be remembered for this session.
 */
async function warnOnce($: EngineInterface, window: LimitWindow, thresholds: readonly number[], now: number): Promise<void> {
  const key = warnKeyOf(window)
  const isStored = window.resetsAt !== undefined
  const already = isStored ? warnedIn(await $.store.get(key)) : ((await read($, sessionWarned))[key] ?? [])
  const fresh = newlyCrossed(window, thresholds, already)

  if (fresh.length === 0) {
    return
  }

  const all = [...already, ...fresh]

  if (isStored) {
    await $.store.set(key, all)
  } else {
    await update($, sessionWarned, map => ({ ...map, [key]: all }))
  }

  const reset = resetIn(window, now)
  const tail = reset === null ? '' : `, resets in ${reset}`
  $.ui.toast(`${labelOf(window.kind)} limit at ${window.percentUsed}%${tail}`, { timeoutMs: WARN_TOAST_MS })
}

async function pruneWarned($: EngineInterface, now: number): Promise<void> {
  for (const key of expiredWarnKeys(await $.store.keys(), now)) {
    await $.store.delete(key)
  }
}

async function record($: EngineInterface, figures: Figures, settings: Settings): Promise<void> {
  const now = await $.clock.now()
  const next = snapshotOf(figures, now)

  await update($, snapshot, () => next)
  await update($, samples, list => addSamples(list, next))

  if (settings.showsStatus) {
    $.ui.status(shortLine(next))
  }

  const lowest = settings.thresholds[0]

  if (lowest === undefined) {
    return
  }

  for (const window of next.windows) {
    if (window.percentUsed >= lowest) {
      await warnOnce($, window, settings.thresholds, now)
    }
  }
}

export const register: Register = (on, options) => {
  const display = displayOf(options.display)
  const thresholds = parseThresholds(String(options.warnAt ?? '80,95'))
  const ttlMinutes = Number(options.cacheTtlMinutes ?? 60)
  const isAlwaysOn = display === 'band' || display === 'both'
  const drawsBand = isAlwaysOn || display === 'auto'
  const settings: Settings = { showsStatus: display === 'status' || display === 'both', thresholds }

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: COMMAND, description: 'Show subscription limits, burn pace, context and cache state' })
    await pruneWarned($, await $.clock.now())
    await record($, await $.session.usage(), settings)
    $.clock.every(TICK_MS, () => {
      void update($, tick, n => n + 1)
    })

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await record($, e, settings)

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const ended = await $.clock.now()
    await update($, lastTurnEndAt, () => ended)

    return next(e)
  })

  on('command.run', { command: COMMAND }, async $ => {
    const now = await $.clock.now()
    const current = snapshotOf(await $.session.usage(), now)
    const cache = cacheOf(await read($, lastTurnEndAt), now, ttlMinutes, current.contextTokens)
    await update($, isHidden, () => false)
    await update($, dismissed, () => [])

    return { text: report(current, await read($, samples), now, cache) }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!drawsBand || e.props.hasSurvey) {
      return next(e)
    }

    const current = await read($, snapshot)

    if (current === null || (isAlwaysOn && (await read($, isHidden)))) {
      return next(e)
    }

    await read($, tick)
    const now = await $.clock.now()
    const endedAt = e.props.isWorking ? null : await read($, lastTurnEndAt)
    const cache = cacheOf(endedAt, now, ttlMinutes, current.contextTokens)
    const isNarrow = e.props.bodyColumns < NARROW_COLUMNS
    const alerts = alertsOf({
      snapshot: current,
      samples: await read($, samples),
      now,
      thresholds,
      cache,
      isNarrow,
      includesHigh: !isAlwaysOn,
    })
    const { Box, Button, Text } = $.ui.resolve(e)

    const alertLine = (alert: Alert, close: JSX.Element | null) => (
      <Box key={alert.key}>
        <Text color={alert.tone}>{alert.head}</Text>
        {alert.rest !== '' && <Text wrap={isNarrow ? 'truncate' : 'wrap'}> · {alert.rest}</Text>}
        {close !== null && <Text>{'  '}</Text>}
        {close}
      </Box>
    )

    if (!isAlwaysOn) {
      const gone = await read($, dismissed)
      const shown = alerts.filter(alert => !gone.includes(alert.key))

      if (shown.length === 0) {
        return next(e)
      }

      const keys = shown.map(alert => alert.key)
      const close = (
        <Button key="hide" label={CLOSE_LABEL} plain dimColor role="dismiss" onPress={() => update($, dismissed, list => [...list, ...keys])} />
      )

      return <Box flexDirection="column">{shown.map((alert, index) => alertLine(alert, index === 0 ? close : null))}</Box>
    }

    const windows = current.windows.map(window => {
      const tone = toneOf(window.percentUsed)
      const cells = barCells(window.percentUsed)
      const reset = resetIn(window, now)

      return (
        <Box key={window.kind}>
          <Text dimColor>{labelOf(window.kind)} </Text>
          {cells.filled !== '' && <Text color={tone}>{cells.filled}</Text>}
          {cells.empty !== '' && <Text dimColor>{cells.empty}</Text>}
          <Text color={tone}> {Math.round(window.percentUsed)}%</Text>
          {reset !== null && !isNarrow && <Text dimColor> ↻{reset}</Text>}
          <Text>{'  '}</Text>
        </Box>
      )
    })
    const cost = isNarrow ? null : costText(current.costUsd)

    return (
      <Box flexDirection="column">
        <Box>
          {windows}
          {current.contextPercent !== undefined && <Text dimColor>ctx {current.contextPercent}%{'  '}</Text>}
          {cost !== null && <Text dimColor>{cost}{'  '}</Text>}
          <Button key="hide" label={CLOSE_LABEL} plain dimColor role="dismiss" onPress={() => update($, isHidden, () => true)} />
        </Box>
        {alerts.map(alert => alertLine(alert, null))}
      </Box>
    )
  })
}

