import type { LimitSample, LimitSnapshot, LimitWindow } from '../types'

const MINUTE_MS = 60_000
const HOUR_MS = 60 * MINUTE_MS
const DAY_MS = 24 * HOUR_MS

/** How far back the burn rate looks; older samples describe a different pace. */
export const PACE_WINDOW_MS = 30 * MINUTE_MS
/** A pace measured over less time than this is one prompt's spike, not a trend. */
export const MIN_PACE_SPAN_MS = 10 * MINUTE_MS
/** Samples kept per session; enough for the pace window at one sample a minute. */
export const MAX_SAMPLES = 120
const BAR_WIDTH = 8
const BAR_FILLED = '━'
const BAR_EMPTY = '─'
const FULL_PERCENT = 100
const YELLOW_AT = 70
const RED_AT = 90
const WARN_KEY_PREFIX = 'warned:'

const LABELS: Record<string, string> = { five_hour: '5h', seven_day: '7d', spend_limit: 'spend' }

export const labelOf = (kind: string): string => LABELS[kind] ?? kind

export const DISPLAYS = ['auto', 'band', 'status', 'both', 'off'] as const
export type Display = (typeof DISPLAYS)[number]

/** The `display` setting; anything unknown falls back to the quiet default. */
export const displayOf = (value: unknown): Display => DISPLAYS.find(mode => mode === value) ?? 'auto'

export type Tone = 'yellow' | 'red'

/** Color is for the part that needs attention; below 70% a window stays uncolored. */
export const toneOf = (percent: number): Tone | undefined =>
  percent >= RED_AT ? 'red' : percent >= YELLOW_AT ? 'yellow' : undefined

export const barCells = (percent: number, width = BAR_WIDTH): { filled: string; empty: string } => {
  const clamped = Math.max(0, Math.min(FULL_PERCENT, percent))
  const filled = Math.round((clamped / FULL_PERCENT) * width)

  return { filled: BAR_FILLED.repeat(filled), empty: BAR_EMPTY.repeat(width - filled) }
}

export const bar = (percent: number, width = BAR_WIDTH): string => {
  const cells = barCells(percent, width)

  return cells.filled + cells.empty
}

export const duration = (ms: number): string => {
  if (ms < MINUTE_MS) {
    return '<1m'
  }

  if (ms < HOUR_MS) {
    return `${Math.round(ms / MINUTE_MS)}m`
  }

  if (ms < DAY_MS) {
    const hours = Math.floor(ms / HOUR_MS)
    const minutes = Math.round((ms % HOUR_MS) / MINUTE_MS)

    return minutes === 0 ? `${hours}h` : `${hours}h ${minutes}m`
  }

  const days = Math.floor(ms / DAY_MS)
  const hours = Math.round((ms % DAY_MS) / HOUR_MS)

  return hours === 0 ? `${days}d` : `${days}d ${hours}h`
}

export const compactTokens = (tokens: number): string =>
  tokens >= 1000 ? `${Math.round(tokens / 1000)}k` : String(tokens)

export const costText = (usd: number | undefined): string | null =>
  usd === undefined || usd <= 0 ? null : `$${usd.toFixed(2)}`

/** Adds one reading per window, dropping samples of a window that has since reset. */
export const addSamples = (samples: readonly LimitSample[], snapshot: LimitSnapshot): LimitSample[] => {
  const next = [...samples]

  for (const window of snapshot.windows) {
    const sample: LimitSample = { at: snapshot.at, kind: window.kind, percentUsed: window.percentUsed }

    if (window.resetsAt !== undefined) {
      sample.resetsAt = window.resetsAt
    }

    next.push(sample)
  }

  const current = new Map(snapshot.windows.map(window => [window.kind, window.resetsAt]))

  return next
    .filter(sample => !current.has(sample.kind) || current.get(sample.kind) === sample.resetsAt)
    .slice(-MAX_SAMPLES)
}

export type Pace =
  | { kind: 'unknown' }
  | { kind: 'idle' }
  | { kind: 'lasts'; percentPerHour: number }
  | { kind: 'runs-out'; percentPerHour: number; inMs: number; beforeResetMs: number | null }

/** Percent per millisecond over the pace window, from the first and last sample of one window. */
export const paceOf = (samples: readonly LimitSample[], window: LimitWindow, now: number): Pace => {
  const recent = samples.filter(
    sample => sample.kind === window.kind && sample.resetsAt === window.resetsAt && now - sample.at <= PACE_WINDOW_MS,
  )
  const first = recent[0]
  const last = recent[recent.length - 1]

  if (first === undefined || last === undefined || last.at - first.at < MIN_PACE_SPAN_MS) {
    return { kind: 'unknown' }
  }

  const perMs = (last.percentUsed - first.percentUsed) / (last.at - first.at)

  if (perMs <= 0) {
    return { kind: 'idle' }
  }

  const percentPerHour = perMs * HOUR_MS
  const inMs = (FULL_PERCENT - window.percentUsed) / perMs
  const resetAt = window.resetsAt === undefined ? Number.NaN : Date.parse(window.resetsAt)

  if (Number.isNaN(resetAt)) {
    return { kind: 'runs-out', percentPerHour, inMs, beforeResetMs: null }
  }

  const untilReset = resetAt - now

  return inMs < untilReset
    ? { kind: 'runs-out', percentPerHour, inMs, beforeResetMs: untilReset - inMs }
    : { kind: 'lasts', percentPerHour }
}

export const resetIn = (window: LimitWindow, now: number): string | null => {
  if (window.resetsAt === undefined) {
    return null
  }

  const at = Date.parse(window.resetsAt)

  return Number.isNaN(at) ? null : duration(Math.max(0, at - now))
}

/** Thresholds as the settings field spells them: "80,95" → [80, 95], invalid parts dropped. */
export const parseThresholds = (text: string): number[] =>
  text
    .split(',')
    .map(part => Number(part.trim()))
    .filter(value => Number.isFinite(value) && value > 0 && value <= FULL_PERCENT)
    .sort((a, b) => a - b)

/** The thresholds a window crossed that were not warned about yet. */
export const newlyCrossed = (window: LimitWindow, thresholds: readonly number[], warned: readonly number[]): number[] =>
  thresholds.filter(threshold => window.percentUsed >= threshold && !warned.includes(threshold))

/** One store key per window: its kind and when it resets, so the next window starts clean. */
export const warnKeyOf = (window: LimitWindow): string => `${WARN_KEY_PREFIX}${window.kind}:${window.resetsAt ?? ''}`

/** Warn keys whose window has reset; a key without a reset time is never pruned here. */
export const expiredWarnKeys = (keys: readonly string[], now: number): string[] =>
  keys.filter(key => {
    if (!key.startsWith(WARN_KEY_PREFIX)) {
      return false
    }

    const rest = key.slice(WARN_KEY_PREFIX.length)
    const resetAt = Date.parse(rest.slice(rest.indexOf(':') + 1))

    return !Number.isNaN(resetAt) && resetAt <= now
  })

/** The thresholds a stored value says were warned; anything malformed counts as none. */
export const warnedIn = (value: unknown): number[] =>
  Array.isArray(value) ? value.filter((item): item is number => typeof item === 'number' && Number.isFinite(item)) : []

export type Cache = { isCold: false } | { isCold: true; idleMs: number; tokens: number | undefined }

export const cacheOf = (lastTurnEndAt: number | null, now: number, ttlMinutes: number, tokens: number | undefined): Cache => {
  if (lastTurnEndAt === null || ttlMinutes <= 0) {
    return { isCold: false }
  }

  const idleMs = now - lastTurnEndAt

  return idleMs > ttlMinutes * MINUTE_MS ? { isCold: true, idleMs, tokens } : { isCold: false }
}

export const paceText = (pace: Pace): string | null => {
  switch (pace.kind) {
    case 'runs-out':
      return pace.beforeResetMs === null
        ? `runs out in ~${duration(pace.inMs)}`
        : `runs out in ~${duration(pace.inMs)}, ${duration(pace.beforeResetMs)} before reset`
    case 'lasts':
      return 'lasts until reset'
    case 'idle':
    case 'unknown':
      return null
  }
}

/**
 * One line the band shows: `head` is the colored part, `rest` what follows it.
 * `key` changes when the alert gets worse, so a dismissed alert comes back then.
 */
export type Alert = { key: string; tone: Tone; head: string; rest: string }

export type AlertInput = {
  snapshot: LimitSnapshot
  samples: readonly LimitSample[]
  now: number
  thresholds: readonly number[]
  cache: Cache
  isNarrow: boolean
  /** False on the always-on band, whose bars already show a high window. */
  includesHigh: boolean
}

const windowAlert = (window: LimitWindow, input: AlertInput): Alert | null => {
  const pace = paceOf(input.samples, window, input.now)
  const runsOut = pace.kind === 'runs-out'
  const level = input.thresholds.filter(threshold => window.percentUsed >= threshold).at(-1)
  const isHigh = input.includesHigh && level !== undefined

  if (!runsOut && !isHigh) {
    return null
  }

  const reset = resetIn(window, input.now)
  const parts: string[] = []

  // A narrow line has room for one time; when the window runs out first, that is the one that matters.
  if (reset !== null && !(input.isNarrow && runsOut)) {
    parts.push(input.isNarrow ? `↻${reset}` : `resets in ${reset}`)
  }

  if (pace.kind === 'runs-out') {
    const inText = duration(pace.inMs)
    parts.push(
      input.isNarrow
        ? `runs out in ~${inText} — slow down`
        : `at this pace runs out in ~${inText} — slow down or switch to Sonnet`,
    )
  }

  return {
    key: `${window.kind}:${window.resetsAt ?? ''}:${level ?? 0}${runsOut ? ':pace' : ''}`,
    tone: runsOut ? 'red' : (toneOf(window.percentUsed) ?? 'yellow'),
    head: `${labelOf(window.kind)} ${Math.round(window.percentUsed)}%`,
    rest: parts.join(' · '),
  }
}

const coldAlert = (cache: Extract<Cache, { isCold: true }>, now: number, isNarrow: boolean): Alert => {
  const idle = `idle ${duration(cache.idleMs)}`
  const tokens = cache.tokens === undefined ? 'the whole context' : `~${compactTokens(cache.tokens)} tokens`

  return {
    key: `cold:${now - cache.idleMs}`,
    tone: 'yellow',
    head: isNarrow ? 'Cache cold' : 'Cache likely cold',
    rest: isNarrow ? `${idle} · /clear if new task` : `${idle} · next prompt re-reads ${tokens} · /clear if switching tasks`,
  }
}

/** Everything worth acting on right now, worst windows first, the cold cache last. */
export const alertsOf = (input: AlertInput): Alert[] => {
  const alerts = input.snapshot.windows
    .map(window => windowAlert(window, input))
    .filter((alert): alert is Alert => alert !== null)

  if (input.cache.isCold) {
    alerts.push(coldAlert(input.cache, input.now, input.isNarrow))
  }

  return alerts
}

export const alertText = (alert: Alert): string => (alert.rest === '' ? alert.head : `${alert.head} · ${alert.rest}`)

/** One short line for the status line. */
export const shortLine = (snapshot: LimitSnapshot): string => {
  const parts = snapshot.windows.map(window => `${labelOf(window.kind)} ${Math.round(window.percentUsed)}%`)

  if (snapshot.contextPercent !== undefined) {
    parts.push(`ctx ${snapshot.contextPercent}%`)
  }

  const cost = costText(snapshot.costUsd)

  if (cost !== null) {
    parts.push(cost)
  }

  return parts.join(' · ')
}

/** The whole picture as plain text, what /limits prints. */
export const report = (snapshot: LimitSnapshot, samples: readonly LimitSample[], now: number, cache: Cache): string => {
  const lines: string[] = []

  if (snapshot.windows.length === 0) {
    lines.push('No subscription limits reported (API key, or no response yet).')
  }

  for (const window of snapshot.windows) {
    const reset = resetIn(window, now)
    const pace = paceOf(samples, window, now)
    const parts = [`${labelOf(window.kind)}: ${bar(window.percentUsed)} ${window.percentUsed}%`]

    if (reset !== null) {
      parts.push(`resets in ${reset}`)
    }

    if (pace.kind === 'lasts' || pace.kind === 'runs-out') {
      parts.push(`pace ${pace.percentPerHour.toFixed(1)}%/h`)
    }

    const said = paceText(pace)

    if (said !== null) {
      parts.push(said)
    }

    lines.push(parts.join(' · '))
  }

  if (snapshot.contextPercent !== undefined) {
    const tokens = snapshot.contextTokens === undefined ? '' : ` (${compactTokens(snapshot.contextTokens)} tokens)`
    lines.push(`context: ${bar(snapshot.contextPercent)} ${snapshot.contextPercent}%${tokens}`)
  }

  if (snapshot.costUsd !== undefined) {
    lines.push(`session cost: $${snapshot.costUsd.toFixed(2)}`)
  }

  if (cache.isCold) {
    lines.push(alertText(coldAlert(cache, now, false)))
  }

  return lines.join('\n')
}

