export type LimitWindow = { kind: string; percentUsed: number; resetsAt?: string }

export type LimitSnapshot = {
  at: number
  windows: LimitWindow[]
  contextPercent?: number
  contextTokens?: number
  costUsd?: number
}

export type LimitSample = { at: number; kind: string; percentUsed: number; resetsAt?: string }

declare module 'claude-code' {
  interface PluginState {
    'limit-radar': {
      snapshot: LimitSnapshot | null
      samples: LimitSample[]
      lastTurnEndAt: number | null
      tick: number
      isHidden: boolean
      dismissed: string[]
      sessionWarned: Record<string, number[]>
    }
  }
}
